def fits(input_tokens, output_tokens, safety_margin, capacity):
    values = (input_tokens, output_tokens, safety_margin, capacity)
    if any(isinstance(value, bool) or not isinstance(value, int) or value < 0 for value in values):
        raise ValueError("All arguments must be nonnegative integers, excluding bool")
    return input_tokens + output_tokens + safety_margin <= capacity
